def transform(grid):
    h, w = len(grid), len(grid[0])
    # Identify the orientation of the colored guide stripes.
    cells = [(r, c, v) for r in range(h) for c, v in enumerate(grid[r]) if v]
    dirs = [(0, 1), (1, 0), (1, 1), (1, -1)]
    def line_key(r, c, dr, dc):
        if dr == 0: return r
        if dc == 0: return c
        if dr == dc: return c-r
        return c+r
    best = None
    for dr, dc in dirs:
        groups = {}
        for r,c,v in cells:
            groups.setdefault(line_key(r,c,dr,dc), []).append((r,c,v))
        # count the direction yielding the most long, monochromatic lines
        score = sum(1 for g in groups.values() if len(g) >= 2 and len({x[2] for x in g}) == 1)
        if best is None or score > best[0]: best = (score, dr, dc, groups)
    _, dr, dc, groups = best
    seeds = {}
    for k, g in groups.items():
        colors = {x[2] for x in g}
        if len(colors) == 1:
            seeds[k] = next(iter(colors))
    # Guide stripes encode one full repeating diagonal/row sequence.
    period = len(seeds)
    if not period:
        return [row[:] for row in grid]
    mapping = {k % period: v for k, v in seeds.items()}
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            k = line_key(r,c,dr,dc)
            row.append(mapping[k % period])
        out.append(row)
    return out
